// Finance: expenses, P&L, exports.
// Owner: Agent D1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { isoDate, optionalText, positiveMinor, text, uuid } from './common';

export const financeContractsVersion = 2 as const;

export const EXPENSE_KINDS = ['cogs', 'labor', 'rent', 'utilities', 'marketing', 'delivery', 'fees', 'maintenance', 'other'] as const;
export const expenseKind = z.enum(EXPENSE_KINDS);
export type ExpenseKind = (typeof EXPENSE_KINDS)[number];

export const financePeriod = z.object({
  from: isoDate,
  to: isoDate,
  branchId: uuid.optional(),
}).refine((p) => p.to >= p.from, { message: 'The period end must not be before its start', path: ['to'] })
  .refine((p) => (Date.parse(p.to) - Date.parse(p.from)) / 864e5 <= 366, { message: 'Choose a period of at most one year', path: ['to'] });
export type FinancePeriod = z.infer<typeof financePeriod>;

export const expenseCategoryInput = z.object({ name: text(80), nameAr: optionalText(80), kind: expenseKind });

export const expenseInput = z.object({
  categoryId: uuid,
  branchId: uuid.nullable().optional(),
  amountMinor: positiveMinor,
  /** Reclaimable input VAT included in amountMinor. */
  taxMinor: z.number().int().min(0).max(1e13).default(0),
  incurredOn: isoDate,
  vendor: optionalText(120),
  description: optionalText(500),
  paymentMethod: optionalText(40),
  externalRef: optionalText(120),
}).refine((e) => e.taxMinor <= e.amountMinor, { message: 'Tax cannot exceed the amount', path: ['taxMinor'] });
export type ExpenseInput = z.infer<typeof expenseInput>;
export const expenseUpdate = z.object({
  categoryId: uuid.optional(),
  branchId: uuid.nullable().optional(),
  amountMinor: positiveMinor.optional(),
  taxMinor: z.number().int().min(0).max(1e13).optional(),
  incurredOn: isoDate.optional(),
  vendor: optionalText(120),
  description: optionalText(500),
  paymentMethod: optionalText(40),
  externalRef: optionalText(120),
});

export const listExpensesQuery = z.object({
  from: isoDate.optional(),
  to: isoDate.optional(),
  categoryId: uuid.optional(),
  branchId: uuid.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});

export const EXPORT_KINDS = ['sales', 'payments', 'expenses', 'pnl', 'tax'] as const;
export const createExport = z.object({
  kind: z.enum(EXPORT_KINDS),
  from: isoDate,
  to: isoDate,
  branchId: uuid.optional(),
}).refine((p) => p.to >= p.from, { message: 'The period end must not be before its start', path: ['to'] });
export type CreateExport = z.infer<typeof createExport>;

export const accountingPush = z.object({
  connectionId: uuid,
  from: isoDate,
  to: isoDate,
  branchId: uuid.optional(),
  key: z.string().min(8).max(200),
}).refine((p) => p.to >= p.from, { message: 'The period end must not be before its start', path: ['to'] });

// ---------------------------------------------------------------------------
// Response shapes
// ---------------------------------------------------------------------------

export interface FinanceRevenueTotals {
  orderCount: number;
  grossMinor: number;
  discountsMinor: number;
  refundsMinor: number;
  netMinor: number;
  vatMinor: number;
  netExVatMinor: number;
  collectedMinor: number;
}

export interface RevenueOverview {
  period: { from: string; to: string; branchId: string | null };
  currency: string;
  totals: FinanceRevenueTotals;
  byDay: Array<{ date: string } & FinanceRevenueTotals>;
  byBranch: Array<{ branchId: string; name: string } & FinanceRevenueTotals>;
  byMethod: Array<{ method: string; collectedMinor: number; refundedMinor: number; count: number }>;
  warnings: string[];
}

export interface ProfitAndLoss {
  period: { from: string; to: string; branchId: string | null };
  currency: string;
  lines: {
    grossSalesMinor: number;
    discountsMinor: number;
    refundsMinor: number;
    vatMinor: number;
    netRevenueMinor: number;
    cogsFromSalesMinor: number;
    cogsExpensesMinor: number;
    cogsMinor: number;
    grossProfitMinor: number;
    operatingExpensesMinor: number;
    operatingExpensesByKind: Record<string, number>;
    paymentFeesMinor: number;
    operatingProfitMinor: number;
  };
  /** Basis points (1234 = 12.34%); null when there is no net revenue. */
  grossMarginBp: number | null;
  operatingMarginBp: number | null;
  methodology: string[];
  coverage: { linesWithoutCost: number; salesWithoutCostMinor: number; unpaidOrders: number; paymentsWithUnknownFee: number; testPayments: number };
  warnings: string[];
}
